def parse_nested_parens_v2(paren_string: str) -> List[int]:
    """ Same as the above function, but more efficient using dynamic programming
    (based on this Python snippet from https://gist.github.com/alexmanos/b1a409a119a419bb7686a2d58823252d)
    """
    if len(paren_string) == 0:
        return []

    stack = []
    levels = []
    for i, c in enumerate(paren_string):
        if c == '(':
            stack.append(i)
        else:
            if len(stack) > 0:
                levels.append(max(i - stack[-1] for i in stack))
            del stack[-1]

    if len(stack) > 0:
        return max(levels)
    else:
        return levels


