def solve_nested_parens(paren_string: str) -> int:    
    counter = 0
    inside = False
    for char in range(len(paren_string) - 1, -1, -1):
        if paren_string[char] == "(":
            counter += 1
        elif paren_string[char] == ")":
            if inside and counter > 0:
                counter -= 1
            else:
                break    
        else:
            if inside:
                inside = False
            else:
                if counter == 0:
                    inside = True
                else:
                    counter -= 1                
        counter = max(0, counter)

    return counter


