def mean_squared_error(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate mean squared error
    >>> mean_squared_error([1.0, 2.0, 3.0, 4.0])
    1.75
    """
    sum_diffs = sum(
        [
            abs(x - float("{:.3f}".format(x_mean))) ** 2
            for x, x_mean in (
                (number, sum(numbers) / len(numbers)) for number in numbers
            )
        ]
    )
    MSE = float("{:.3f}".format(sum_diffs / len(numbers)))
    return float(MSE)


