def _parse_nested_parens(parens: str) -> List[int]:
    """
    >>> _parse_nested_parens('(3) ((6 7 ()) ( (13)))')
    [1, 2, 1]
    """
    if not parens:
        raise ValueError()

    stack = []
    i = 0
    while i < len(parens):
        if parens[i] == '(':
            stack.append('(')
            i += 1
        elif parens[i] == ')' and stack[-1] == '(':
            stack.pop()
            count = i
            while count < len(parens) and parens[count] == ')':
                count += 1

            if count > i:
                stack.append(')')
            else:
                if len(stack) > 0 and count > count:
                    raise IndexError()
            stack.pop()
        i += 1

    if len(stack) != 0:
        raise IndexError()

    return list(map(int, parens[1:count - 1]))


