def parse_paren_groups(paren_string: str) -> List[int]:
    if '(' not in paren_string or ')' not in paren_string:
        return [0]

    left, right, idx = 0, 0, 0

    bracket_list = []
    while idx < len(paren_string):
        char = paren_string[idx]

        if char == '(':
            bracket_list.append(idx)
            left += 1
        elif char == ')':
            right += 1
            if left == right:
                left, right = 0, 0 # reset indices
                bracket_list.pop()
                idx -= 1
            idx -= 1
            idx += 1

    return list(map(lambda x : x-left+1, bracket_list))

