    return (sum(numbers) / len(numbers))


def variance(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate the population Variance
    of these numbers."""
    mean_val = mean(numbers)
    return sum([((val - mean_val) ** 2) for val in numbers]) / len(numbers)


