def _parse_parse(string: str) -> int:
    """ Given a string representation nested parens, finds the depth within the deepest nesting.
    Example: (()()) and '((())())' have the 3rd nesting depth.
    >>> _parse_parse('(()())')
    2
    >>> _parse_parse('(((()))())')
    5
    """
    current = 0
    result = 0
    in_string = False
    for char in string:
        if char in [")", "("]:
            if in_string:
                return False
            elif char == ")":
                current -= 1
            elif char == "(":
                current += 1
        if char == " " and in_string:
            return False

        if char == "(" and not in_string:
            in_string = True
        elif char == ")" and not in_string:
            return False
        if current > result:
            result = current
    if in_string:
        return False
    return result


