    """
    >>> filter_duplicates(['hello', 'world', 'helloworld', 'there', 'world'])
    ['helloworld', 'world']
    """
    return [
        string
        for string in set(strings)
    ]


def filter_by_regex(strings: List[str], regex: str) -> List[str]:
    """
    >>> filter_by_regex(['hello', 'world', 'foo-bar', 'the cat'], '([a-zA-Z]+-)foo')
    ['foo-bar']
    """
    return [
        string
        for string in strings
        if bool(regex.match(string))
    ]


